dtsPropsFor.Alert:
/** Status tone. Sets the left-rule colour and the ARIA role (error and warning announce as role="alert", info and success as role="status"). Default 'info'. */
variant?: 'info' | 'warning' | 'error' | 'success';
/** Optional first line, set above the message. */
title?: React.ReactNode;
/** The message body. */
children?: React.ReactNode;
className?: string;

dtsPropsFor.Avatar:
/** xs 24px, sm 32px, md 48px, lg 64px. Default 'md'. */
size?: 'xs' | 'sm' | 'md' | 'lg';
/** Image URL. When absent or it fails to load, initials from `name` render instead. */
src?: string;
/** Person or entity name. Source of the initials fallback and the aria-label. */
name?: string;
className?: string;

dtsPropsFor.StatusPill:
/** How the state feels. progress and live glow by default; live sets its label in capitals; neutral (planned) has no fill, a dashed edge. Default 'neutral'. */
tone?: 'progress' | 'success' | 'warning' | 'error' | 'info' | 'neutral' | 'live';
/** filled for the state that matters on a row; outline where pills sit together or for a pass / fail verdict. Default 'filled'. */
emphasis?: 'filled' | 'outline';
/** The whole pill glows in its hue and the glow breathes: the thing is still running. Defaults to true for progress and live; false turns it off. */
glow?: boolean;
/** Optional leading Phosphor glyph (rendered bold). */
icon?: React.ComponentType<any>;
/** The product's own word, one or two words. */
children?: React.ReactNode;
className?: string;

dtsPropsFor.Button:
/** primary rests neutral and turns teal on hover; secondary is an ink-outline pill (transparent ground, label turns teal on hover); tertiary is a teal text ghost; destructive is the error fill. Default 'primary'. */
variant?: 'primary' | 'secondary' | 'tertiary' | 'destructive';
/** lg = the standard control; sm = the compact chip for dense rows (11/medium label, 12 × 4 padding, 12px icon). Every variant and state exists at both sizes. Default 'lg'. */
size?: 'lg' | 'sm';
disabled?: boolean;
/** Dims the label, swaps the arrow for a spinner, sets aria-busy, and suppresses onClick. */
loading?: boolean;
/** Trailing arrow glyph. Default true. */
arrow?: boolean;
/** Default 'button'. */
type?: 'button' | 'submit' | 'reset';
/** The label. */
children?: React.ReactNode;
onClick?: (event: React.MouseEvent<HTMLButtonElement>) => void;
className?: string;
/** Any other native <button> attribute passes through to the element. */
[attr: string]: unknown;

dtsPropsFor.Card:
/** default = sunk tile; interactive = renders a <button>, deepens on hover/focus; elevated = page-ground fill that lifts against sunk surroundings. Default 'default'. */
variant?: 'default' | 'interactive' | 'elevated';
/** Element to render for the non-interactive variants. Default 'div'. Ignored when variant is 'interactive'. */
as?: React.ElementType;
/** Fires only when variant is 'interactive'. */
onClick?: (event: React.MouseEvent<HTMLButtonElement>) => void;
/** Card content. The card sets its own padding. */
children?: React.ReactNode;
className?: string;
/** Any other HTML attribute passes through to the element. */
[attr: string]: unknown;

dtsPropsFor.Divider:
/** Default 'horizontal'. A vertical divider is an inline rule that stretches to its flex row's height. */
orientation?: 'horizontal' | 'vertical';
/** Centred label between two rules. Horizontal only. */
label?: React.ReactNode;
className?: string;

dtsPropsFor.Icon:
/** A Phosphor icon component, e.g. `SCDS.Gear` or `SCDS.MagnifyingGlass`. Renders nothing when missing. */
glyph: React.ComponentType<any>;
/** Phosphor weight. Default 'regular'. */
weight?: 'thin' | 'light' | 'regular' | 'bold' | 'fill' | 'duotone';
/** 'sm' 16px, 'md' 24px, 'lg' 32px (token sizes), or any px number / CSS length. Default '1em' (follows the surrounding font-size). */
size?: 'sm' | 'md' | 'lg' | number | string;
/** Accessible name. With it the icon is announced as an image; without it the icon is aria-hidden. */
label?: string;
className?: string;
/** Any other SVG attribute passes through to the element. */
[attr: string]: unknown;

dtsPropsFor.Input:
/** Visible label, wired to the input. */
label?: React.ReactNode;
/** Helper text under the field. */
helper?: React.ReactNode;
/** Error text. Replaces the helper, turns the field to the error state, and sets aria-invalid. */
error?: React.ReactNode;
disabled?: boolean;
/** Native input type. Default 'text'. */
type?: string;
/** Controlled value. Pair with onChange; use defaultValue for an uncontrolled field. */
value?: string;
defaultValue?: string;
onChange?: (event: React.ChangeEvent<HTMLInputElement>) => void;
placeholder?: string;
className?: string;
/** Any other native <input> attribute passes through to the element. */
[attr: string]: unknown;

dtsPropsFor.NavBar:
/** Brand slot at the leading edge: a wordmark or logo node. */
brand?: React.ReactNode;
/** Navigation links. Set `current` on the active page (renders aria-current="page"). */
links?: Array<{ href: string; label: React.ReactNode; current?: boolean }>;
/** Trailing action slot, usually one Button. */
trailing?: React.ReactNode;
/** Mobile layout: brand plus a Menu toggle that reveals the stacked links. The component does not switch by itself; pass this at narrow widths. */
compact?: boolean;
className?: string;

dtsPropsFor.ProgressIndicator:
/** bar = linear track; circular = ring; step = numbered dots with connectors. Default 'bar'. */
variant?: 'bar' | 'circular' | 'step';
/** Progress for bar and circular, from 0 to 1. Default 0.5. */
value?: number;
/** step variant: total number of steps. Default 4. */
steps?: number;
/** step variant: index of the current step, 0-based. Earlier steps render as done. Default 1. */
current?: number;
/** Non-interactive bar only: fill colour. accent = brand teal; progress = signal chartreuse; warning = status warning. Use tones to rank several meters side by side. Default 'accent'. */
tone?: 'accent' | 'progress' | 'warning';
/** Non-interactive bar only: track well. sunk is the deeper well a meter on a raised tile needs. Default 'deepSunk'. */
track?: 'deepSunk' | 'sunk';
/** Accessible name (aria-label) for bar and circular. */
label?: string;
/** bar variant only: makes the bar a draggable, keyboard-operable slider (role="slider"). Controlled: pair value with onChange. */
interactive?: boolean;
/** Interactive bar: receives the new value while dragging or on arrow keys. */
onChange?: (value: number) => void;
/** Interactive bar bounds and increments. Defaults: min 0, max 1, step 0.01, bigStep 0.05 (Shift + arrow). */
min?: number;
max?: number;
step?: number;
bigStep?: number;
/** Interactive bar only. */
disabled?: boolean;
className?: string;

dtsPropsFor.SegmentedControl:
/** The segments, in order. Two to four short labels. `count` renders a number after the label in the label's own ink. */
options: Array<{ value: string; label: React.ReactNode; count?: React.ReactNode }>;
/** Selected option's value. Controlled: the indicator follows this prop, so pair it with onChange. */
value: string;
onChange?: (value: string) => void;
disabled?: boolean;
/** Accessible name for the radiogroup. */
label?: string;
/** sm = compact; md = default; lg = the 16 × 8 tab-label segment of a tab header. Default 'md'. */
size?: 'sm' | 'md' | 'lg';
/** Plays the `select` role sound when the selection changes (pointer or arrow keys); re-selecting the current segment is silent. false silences this instance; a SoundProvider with enabled={false} silences every instance. Default true. */
sound?: boolean;
className?: string;

dtsPropsFor.Stepper:
/** Current number. Controlled: pair with onChange. */
value: number;
onChange?: (value: number) => void;
/** Lower bound. The minus button disables at it. Default: unbounded. */
min?: number;
/** Upper bound. The plus button disables at it. Default: unbounded. */
max?: number;
/** Increment per press. Default 1. */
step?: number;
/** Accessible name, e.g. "Quantity". Also names the buttons ("Increase Quantity"). */
label?: string;
disabled?: boolean;
/** Plays the `tick` role sound on each committed step, hold-repeat included; a press at min or max commits nothing and stays silent. false silences this instance; a SoundProvider with enabled={false} silences every instance. Default true. */
sound?: boolean;
className?: string;

dtsPropsFor.Switch:
/** On/off state. Controlled: pair with onChange. Default false. */
checked?: boolean;
disabled?: boolean;
onChange?: (event: React.ChangeEvent<HTMLInputElement>) => void;
/** Visible label beside the track. The whole label is the click target. */
label?: React.ReactNode;
/** Plays the `toggle` role sound on each change. false silences this instance; a SoundProvider with enabled={false} silences every instance. Default true. */
sound?: boolean;
className?: string;

dtsPropsFor.Tooltip:
/** Tooltip text. Shown above the child on hover and on keyboard focus. */
content: React.ReactNode;
/** Allow the content to wrap at a readable measure. Default false (single line). */
multiline?: boolean;
/** The trigger. Make it focusable (a button, a link, or tabIndex={0}) so keyboard users reach the tooltip. */
children: React.ReactNode;

dtsPropsFor.WorkingMark:
/** true = accent ink, animated (still under prefers-reduced-motion); false = secondary ink, still ("current but paused"). Default true. */
working?: boolean;
/** sm 16px, md 24px, lg 32px. Default 'sm'. */
size?: 'sm' | 'md' | 'lg';
/** Accessible name. With it the mark is announced as an image; without it the mark is aria-hidden. */
label?: string;
className?: string;
/** Any other SVG attribute passes through to the element. */
[attr: string]: unknown;

dtsPropsFor.PlusField:
/** The art to draw. Turn-2 brand elements: udiv divider, ucardhead card header, ucard card hover, ucta CTA band, uempty empty state, uskel skeleton (animated), uprog progress, uloader page loader (animated), uline active-tab underline, umedia image placeholder, uhero hero background, ufooter footer edge, uquote pull-quote bracket, utime timeline rail, ubullet list bullet, usep breadcrumb separator, uthumb seeded thumbnail, unews form-card corner, usplash app splash (animated), type halftone text. */
art: 'udiv' | 'ucardhead' | 'ucard' | 'ucta' | 'uempty' | 'uskel' | 'uprog' | 'uloader' | 'uline' | 'umedia' | 'uhero' | 'ufooter' | 'uquote' | 'utime' | 'ubullet' | 'usep' | 'uthumb' | 'unews' | 'usplash' | 'type';
/** Ground the field paints, which also sets the mark colour: inverse = on-inverse marks; raised, page, sunk = primary-text marks; none = no ground, primary-text marks. Default 'inverse'. */
surface?: 'inverse' | 'raised' | 'page' | 'sunk' | 'none';
/** Mark shape. plus is the brand mark; square and round are quieter. Default 'plus'. */
shape?: 'plus' | 'square' | 'round';
/** Spacing between marks, 0.6 (open) to 1.6 (packed). Default 1. */
density?: number;
/** Animated arts (uskel, uloader, usplash) only. false shows one still frame, as prefers-reduced-motion does. Default true. */
animate?: boolean;
/** Fixes every random choice: same art + same seed = same picture. Default: the art name. */
seed?: string;
/** udiv: rows of marks (1, 3 or 5). uprog: 1 (thin) or 3 (band). */
rows?: number;
/** udiv: which ends fade. Default 'both'. */
fade?: 'both' | 'end' | 'none';
/** type: the string to draw. Default 'Crafthouse'. */
text?: string;
/** type: glyph height as a share of the box height. Default 0.62. */
textScale?: number;
/** uprog: filled share, 0 to 1. */
progress?: number;
/** ubullet: teal, for the current item only. Default false. */
accent?: boolean;
/** utime: number of nodes, one per equal row of the box height. */
steps?: number;
/** utime: 0-based index of the current (teal) node. Earlier nodes render as done. */
current?: number;
/** Fill the nearest positioned ancestor (position: absolute; inset: 0) instead of the parent box. Put content over it in a positioned element. Default false. */
backdrop?: boolean;
/** uprog: accessible name of the hidden progressbar. uloader, uskel: text of a hidden role=status. */
label?: string;
/** Root element. Use 'span' inside phrasing content such as a button or link. Default 'div'. */
as?: 'div' | 'span';
className?: string;
/** Any other attribute passes through to the root element (e.g. style, to give it a height). */
[attr: string]: unknown;

dtsPropsFor.SectionDivider:
/** hairline = 1 row, faded ends, between paragraphs; band = 3 rows, between sections; block = 5 rows, square ends, a chapter break. Default 'band'. */
weight?: 'hairline' | 'band' | 'block';
/** Paint a ground behind the marks. Default 'none' (sits on the current surface). */
surface?: 'inverse' | 'raised' | 'page' | 'sunk' | 'none';
/** Mark shape. plus is the brand mark; square and round are quieter. Default 'plus'. */
shape?: 'plus' | 'square' | 'round';
/** Spacing between marks, 0.6 (open) to 1.6 (packed). Default 1. */
density?: number;
className?: string;

dtsPropsFor.HeadingRule:
/** title = title-section heading + 3-row band; eyebrow = mono-caption label + 1-row hairline. Default 'title'. */
variant?: 'title' | 'eyebrow';
/** Heading element. Default 'h2' for title, 'p' for eyebrow. */
as?: React.ElementType;
/** The heading text. */
children?: React.ReactNode;
/** Default 'none'. */
surface?: 'inverse' | 'raised' | 'page' | 'sunk' | 'none';
/** Mark shape. plus is the brand mark; square and round are quieter. Default 'plus'. */
shape?: 'plus' | 'square' | 'round';
/** Spacing between marks, 0.6 (open) to 1.6 (packed). Default 1. */
density?: number;
className?: string;

dtsPropsFor.PlusUnderline:
/** true draws the teal indicator; false keeps the same height and draws nothing, so tab labels stay level. Default true. */
active?: boolean;
/** Mark shape. plus is the brand mark; square and round are quieter. Default 'plus'. */
shape?: 'plus' | 'square' | 'round';
/** Spacing between marks, 0.6 (open) to 1.6 (packed). Default 1. */
density?: number;
className?: string;

dtsPropsFor.PlusProgress:
/** Filled share, 0 to 1. Default 0. */
value?: number;
/** thin = 1 row; band = 3 rows. Default 'thin'. */
variant?: 'thin' | 'band';
/** Accessible name of the hidden role=progressbar. Always set it. */
label?: string;
/** Default 'none'. */
surface?: 'inverse' | 'raised' | 'page' | 'sunk' | 'none';
/** Mark shape. plus is the brand mark; square and round are quieter. Default 'plus'. */
shape?: 'plus' | 'square' | 'round';
/** Spacing between marks, 0.6 (open) to 1.6 (packed). Default 1. */
density?: number;
className?: string;

dtsPropsFor.PlusLoader:
