/** false holds the shapes at rest, as prefers-reduced-motion does. Default true. */
animate?: boolean;
/** Mark shape. plus is the brand mark; square and round are quieter. Default 'plus'. */
shape?: 'plus' | 'square' | 'round';
/** Spacing between marks, 0.6 (open) to 1.6 (packed). Default 1. */
